pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DepositLog c;

    function setUp() public {
        c = new DepositLog();
    }

    function _run(address _requester, bytes32 _digest, uint256 _utxoSize, bytes memory _redeemerOutputScript, uint256 _requestedFee, bytes memory _outpoint) internal {
        vm.assume(!c.approvedToLog(address(this)));
        bool obs = c.logRedemptionRequested(_requester, _digest, _utxoSize, _redeemerOutputScript, _requestedFee, _outpoint);
        assertTrue(obs == false);
    }

    function testFuzz_run(address _requester, bytes32 _digest, uint256 _utxoSize, bytes memory _redeemerOutputScript, uint256 _requestedFee, bytes memory _outpoint) public {
        vm.assume(_requester.code.length == 0 && uint160(_requester) > 0xffff && _requester != address(this) && _requester != address(c) && _requester != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _requester != 0x000000000000000000636F6e736F6c652e6c6f67 && _requester != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _requester != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(_requester, _digest, _utxoSize, _redeemerOutputScript, _requestedFee, _outpoint);
    }

    receive() external payable { }
}
